export type NotificationPlan = { tier: 'free' | 'supporter' | 'paid'; planId: string; label: string; slotLimit: number; minuteLimit: number; dayLimit: number; priority: number;
    baseSlotLimit?: number; manualExtraSlots?: number; addonGrantUnits?: number; addonExtraSlots?: number; donationPaymentCount?: number; addonValidUntilAtMs?: number | null };
export type NotificationPlanPolicy = NotificationPlan & { enabled: boolean; isBuiltin: boolean; updatedAtMs: number };
export type NotificationSlot = NotificationPlan & { slotId: string; slotIndex: number; slotCost?: number; targetKind: 'auto' | 'price'; targetId: string };
type Query = (sql: string, params?: unknown[]) => Promise<any>;
type AdminActor = { userId: string; isAdmin?: boolean };
export const FREE_PLAN: NotificationPlan;
export const SUPPORTER_PLAN: NotificationPlan;
export function inspectPlan(query: Query, userId: string, now?: number): Promise<NotificationPlan>;
export function lockOwner(query: Query, userId: string): Promise<string>;
export function assertSlotAvailable(query: Query, userId: string, kind: 'auto' | 'price', targetId?: string | null): Promise<NotificationPlan | NotificationSlot>;
export function assignSlot(query: Query, userId: string, kind: 'auto' | 'price', targetId: string): Promise<NotificationSlot>;
export function releaseSlot(query: Query, userId: string, kind: 'auto' | 'price', targetId: string): Promise<void>;
export function findSlot(query: Query, userId: string, kind: 'auto' | 'price', targetId: string): Promise<NotificationSlot | null>;
export function resolveNotificationEntitlement(db: { withDatabaseTransaction: (work: (query: Query) => Promise<NotificationSlot>) => Promise<NotificationSlot> }, input: { ownerUserId: string; targetKind: 'auto' | 'price'; targetId: string }): Promise<NotificationSlot>;
export function listOwnerSlots(query: Query, userId: string): Promise<NotificationPlan & { usedSlots: number; remainingSlots: number; slots: (NotificationSlot & { allowed: boolean })[] }>;
export function getEntitlementSummary(db: { withDatabaseTransaction: (work: (query: Query) => Promise<any>) => Promise<any> }, userId: string): ReturnType<typeof listOwnerSlots>;
export function savePlanPolicy(query: Query, actor: AdminActor, input: Omit<NotificationPlan, 'tier'> & { enabled?: boolean; expectedUpdatedAtMs?: number }): Promise<NotificationPlanPolicy>;
export function setUserPlan(query: Query, actor: AdminActor, userId: string, planId: string | null, options?: { expiresAtMs?: number | null }): Promise<NotificationPlan>;
export function listPlanPolicies(query: Query, actor: AdminActor): Promise<NotificationPlanPolicy[]>;
